package ru.neverland.townytaxes;

import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import ru.neverland.townytaxes.data.TaxStore;
import ru.neverland.townytaxes.model.*;
import static ru.neverland.townytaxes.model.TaxPayment.Phase.*;

/** Real SQLite WAL, asynchronous acknowledgements, bank fault boundaries and concurrent compare-and-set. */
public final class TaxPaymentsSmoke {
    static int checks;static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    interface Work{void run()throws Exception;}static void reject(Work work,String label)throws Exception{try{work.run();}catch(Exception expected){checks++;return;}throw new AssertionError(label);}
    static <T>T done(CompletionStage<T> future)throws Exception{return future.toCompletableFuture().get(15,TimeUnit.SECONDS);}
    static final UUID SOURCE=UUID.randomUUID(),DEST=UUID.randomUUID(),POLICY=UUID.randomUUID();static long clock=100;
    static TaxPayment receipt(boolean global,TaxPayment.Kind kind,boolean debt){return new TaxPayment(UUID.randomUUID(),kind==TaxPayment.Kind.DEBT?null:POLICY,kind,Domain.Scope.PLAYER,SOURCE,"Player",global?Domain.Scope.GLOBAL:Domain.Scope.TOWN,DEST,"Treasury",TaxCalculation.calculate(10,1,1,1,0),PREPARED,clock++,debt,"Frozen tax terms");}
    static final class Bank implements TaxPayments.Bank {
        long source=100000,destination;int debits,credits,refunds;boolean ready=true,rejectDebit,rejectCredit,loseDebit,loseCredit,loseRefund;Connection lock;String lockedFile;boolean lockAfterDebit;
        final ThreadLocal<Boolean> callback=ThreadLocal.withInitial(()->false);
        public boolean ready(TaxPayment r,TaxPayments.Leg leg){return ready;}
        public boolean apply(TaxPayment r,TaxPayments.Leg leg)throws Exception{
            if(!callback.get())throw new AssertionError("bank called outside supplied server executor");long n=r.calculation().cents();
            return switch(leg){
                case DEBIT->{debits++;if(rejectDebit||source<n)yield false;source-=n;if(lockAfterDebit){lock=DriverManager.getConnection("jdbc:sqlite:"+lockedFile);lock.createStatement().execute("BEGIN IMMEDIATE");}if(loseDebit)throw new Exception("lost acknowledgement after debit");yield true;}
                case CREDIT->{credits++;if(rejectCredit)yield false;destination+=n;if(loseCredit)throw new Exception("lost acknowledgement after credit");yield true;}
                case REFUND->{refunds++;source+=n;if(loseRefund)throw new Exception("lost acknowledgement after refund");yield true;}
            };
        }
        TaxPayments engine(TaxStore store){return new TaxPayments(store,this,task->{boolean old=callback.get();callback.set(true);try{task.run();}finally{callback.set(old);}});}
    }
    static void close(TaxStore store)throws Exception{store.close();done(store.closed());}
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("tax-wal-");Path file=root.resolve("payments.db");var store=new TaxStore(file,20000,Map.of(SOURCE,5000L),false);done(store.ready());check(store.healthy()&&store.snapshot().reserve()==20000&&store.snapshot().debts().get(SOURCE)==5000,"legacy reserve/debt imported exactly once");var bank=new Bank();var engine=bank.engine(store);
        var normal=receipt(false,TaxPayment.Kind.TAX,false);done(store.create(normal));done(engine.process(normal.id()));check(store.get(normal.id()).phase()==DONE&&bank.source==99000&&bank.destination==1000,"confirmed transfer conserves real source and destination");done(engine.process(normal.id()));done(store.create(normal));check(bank.debits==1&&bank.credits==1,"same durable receipt cannot repeat either bank leg");
        var changed=new TaxPayment(normal.id(),normal.policy(),normal.kind(),normal.sourceScope(),normal.sourceId(),normal.sourceName(),normal.destinationScope(),normal.destinationId(),normal.destinationName(),TaxCalculation.calculate(11,1,1,1,0),PREPARED,normal.created(),false,normal.note());var firstStore=store;reject(()->done(firstStore.create(changed)),"receipt ID payload collision rejected");check(store.healthy(),"invalid request does not poison healthy store");
        var debt=receipt(true,TaxPayment.Kind.DEBT,false);done(store.create(debt));done(engine.process(debt.id()));check(store.snapshot().reserve()==21000&&store.snapshot().debts().get(SOURCE)==4000&&bank.source==98000,"debt deduction and internal reserve credit commit with terminal receipt");done(engine.process(debt.id()));check(store.snapshot().reserve()==21000,"internal reserve cannot be credited twice");
        bank.loseDebit=true;var unknown=receipt(false,TaxPayment.Kind.TAX,false);done(store.create(unknown));done(engine.process(unknown.id()));check(store.get(unknown.id()).phase()==DEBITING&&bank.source==97000,"unknown debit held without inventing debt or refund");int calls=bank.debits;done(engine.process(unknown.id()));check(bank.debits==calls,"unknown debit never retried automatically");close(store);
        store=new TaxStore(file,999999,Map.of(SOURCE,999999L),true);done(store.ready());engine=bank.engine(store);check(store.snapshot().reserve()==21000&&store.snapshot().debts().get(SOURCE)==4000,"restart never reimports legacy money/debt");done(engine.process(unknown.id()));check(bank.debits==calls&&store.get(unknown.id()).phase()==DEBITING,"unknown result survives full store restart");bank.loseDebit=false;done(engine.resolve(unknown.id(),TaxPayments.Leg.DEBIT,true));done(engine.process(unknown.id()));check(store.get(unknown.id()).phase()==DONE&&bank.debits==calls&&bank.destination==2000,"applied debit reconciliation continues only missing credit");
        bank.loseCredit=true;var credit=receipt(false,TaxPayment.Kind.TAX,false);done(store.create(credit));done(engine.process(credit.id()));check(store.get(credit.id()).phase()==CREDITING&&bank.destination==3000,"post-credit acknowledgement loss preserves ambiguous credit");int credits=bank.credits;done(engine.process(credit.id()));done(engine.resolve(credit.id(),TaxPayments.Leg.CREDIT,true));check(bank.credits==credits&&store.get(credit.id()).phase()==DONE,"credit reconciliation never deposits again");bank.loseCredit=false;
        bank.rejectCredit=true;var returned=receipt(false,TaxPayment.Kind.TAX,false);done(store.create(returned));long original=bank.source;done(engine.process(returned.id()));check(store.get(returned.id()).phase()==DEBITED&&bank.source==original-1000,"definite receiver refusal retains funded receipt");done(engine.cancel(returned.id()));done(engine.process(returned.id()));check(store.get(returned.id()).phase()==REFUNDED&&bank.source==original,"requested return refunds funded amount exactly once");int refunds=bank.refunds;done(engine.cancel(returned.id()));done(engine.process(returned.id()));check(bank.refunds==refunds,"refund replay cannot create currency");
        var refundLost=receipt(false,TaxPayment.Kind.TAX,false);done(store.create(refundLost));done(engine.process(refundLost.id()));done(engine.cancel(refundLost.id()));bank.loseRefund=true;done(engine.process(refundLost.id()));check(store.get(refundLost.id()).phase()==REFUNDING,"unknown refund has a durable independent phase");refunds=bank.refunds;done(engine.process(refundLost.id()));done(engine.resolve(refundLost.id(),TaxPayments.Leg.REFUND,true));check(bank.refunds==refunds&&store.get(refundLost.id()).phase()==REFUNDED,"unknown refund cannot be issued again");bank.loseRefund=false;bank.rejectCredit=false;
        bank.rejectDebit=true;var unpaid=receipt(false,TaxPayment.Kind.TAX,true);done(store.create(unpaid));done(engine.process(unpaid.id()));check(store.get(unpaid.id()).phase()==REJECTED&&store.snapshot().debts().get(SOURCE)==5000,"only definite source rejection assesses debt");done(engine.process(unpaid.id()));check(store.snapshot().debts().get(SOURCE)==5000,"rejected receipt cannot assess same debt twice");bank.rejectDebit=false;
        bank.ready=false;var waiting=receipt(false,TaxPayment.Kind.TAX,true);done(store.create(waiting));original=bank.source;done(engine.process(waiting.id()));check(store.get(waiting.id()).phase()==PREPARED&&bank.source==original,"unavailable economy pauses before intent without penalty");done(engine.cancel(waiting.id()));check(store.get(waiting.id()).phase()==VOID&&store.snapshot().debts().get(SOURCE)==5000,"admin cancellation before debit creates neither debt nor refund");bank.ready=true;
        var concurrent=receipt(false,TaxPayment.Kind.TAX,false);done(store.create(concurrent));calls=bank.debits;credits=bank.credits;done(CompletableFuture.allOf(engine.process(concurrent.id()).toCompletableFuture(),engine.process(concurrent.id()).toCompletableFuture()));check(bank.debits==calls+1&&bank.credits==credits+1,"competing continuations must win durable CAS before bank call");
        close(store);var lostStore=new TaxStore(root.resolve("missing.db"),0,Map.of(),true);reject(()->done(lostStore.ready()),"missing required database cannot reset money from stale YAML");check(!Files.exists(root.resolve("missing.db")),"missing required DB is not silently created");close(lostStore);
        Path locked=root.resolve("locked.db");var lockedStore=new TaxStore(locked,0,Map.of(),false);done(lockedStore.ready());var lockedBank=new Bank();lockedBank.lockAfterDebit=true;lockedBank.lockedFile=locked.toString();var lockedEngine=lockedBank.engine(lockedStore);var interrupted=receipt(false,TaxPayment.Kind.TAX,false);done(lockedStore.create(interrupted));reject(()->done(lockedEngine.process(interrupted.id())),"actual SQLite write failure after bank debit surfaced");check(lockedBank.debits==1&&!lockedStore.healthy(),"failed durable acknowledgement blocks new financial work");lockedBank.lock.createStatement().execute("ROLLBACK");lockedBank.lock.close();close(lockedStore);
        var recovery=new TaxStore(locked,0,Map.of(),true);done(recovery.ready());var recoveredEngine=lockedBank.engine(recovery);check(recovery.get(interrupted.id()).phase()==DEBITING,"crash boundary retains pre-bank intent on disk");done(recoveredEngine.process(interrupted.id()));check(lockedBank.debits==1,"restart after real database failure cannot repeat debit");lockedBank.lockAfterDebit=false;done(recoveredEngine.resolve(interrupted.id(),TaxPayments.Leg.DEBIT,true));done(recoveredEngine.process(interrupted.id()));check(lockedBank.source+lockedBank.destination==100000&&recovery.get(interrupted.id()).phase()==DONE,"reconciliation restores transfer conservation after lost disk acknowledgement");close(recovery);
        System.out.println("TaxPaymentsSmoke PASS "+checks+" checks");
    }
}
